"""Provision a focused operations overview and a separate review-evidence view."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];DEST=ROOT/'deployment/grafana/dashboards'
DS={'type':'prometheus','uid':'aeris-prometheus'}
SEL='{cohort="$cohort"}'
def target(expr,name,instant=False,table=False):return dict(refId=name,expr=expr,legendFormat=name,instant=instant,range=not instant,format='table' if table else 'time_series',datasource=DS)
def panel(i,title,kind,pos,queries,description,unit='short',color='palette-classic'):
    x,y,w,h=pos
    return dict(id=i,title=title,type=kind,gridPos=dict(x=x,y=y,w=w,h=h),datasource=DS,description=description,targets=queries,fieldConfig={'defaults':{'unit':unit,'color':{'mode':color},'mappings':[],'thresholds':{'mode':'absolute','steps':[{'color':'blue','value':None}]}},'overrides':[]},options={})
def trend(p,stack=False):
    p['fieldConfig']['defaults'].update(min=0,custom=dict(drawStyle='line',lineInterpolation='linear',lineWidth=2,fillOpacity=18 if stack else 5,showPoints='never',spanNulls=False,stacking={'mode':'normal' if stack else 'none','group':'A'},axisLabel='',axisPlacement='auto',thresholdsStyle={'mode':'off'}))
    p['options']=dict(tooltip={'mode':'multi','sort':'desc'},legend={'displayMode':'table','placement':'bottom','calcs':['lastNotNull','max']});return p
def gauge(p,low=0,high=1,threshold=None,no='No observations'):
    if p['fieldConfig']['defaults']['unit']=='percentunit':
        for t in p['targets']:t['expr']='100 * ('+t['expr']+')'
        p['fieldConfig']['defaults']['unit']='percent';low*=100;high*=100
        if threshold is not None:threshold*=100
    d=p['fieldConfig']['defaults'];d.update(min=low,max=high,decimals=1,noValue=no,color={'mode':'thresholds'},mappings=[{'type':'special','options':{'match':'null','result':{'text':no,'color':'#8e8e8e'}}}])
    if threshold is not None:d['thresholds']['steps'].append({'color':'orange','value':threshold})
    p['options']=dict(reduceOptions={'values':False,'calcs':['lastNotNull'],'fields':''},showThresholdLabels=True,showThresholdMarkers=True,orientation='auto');return p
def bars(p,label):
    p['fieldConfig']['defaults'].update(min=0,decimals=0,color={'mode':'fixed','fixedColor':'blue'},custom={'fillOpacity':85,'lineWidth':0,'axisPlacement':'auto'})
    p['transformations']=[{'id':'organize','options':{'excludeByName':{'Time':True,'__name__':True,'cohort':True},'renameByName':{'Value':'Requests'}}}]
    p['options']=dict(orientation='horizontal',xField=label,showValue='always',groupWidth=.7,barWidth=.85,stacking='none',legend={'showLegend':False},tooltip={'mode':'single'},xTickLabelRotation=0,barRadius=.12);return p
def dashboard(uid,title,panels,links):
    return dict(uid=uid,title=title,schemaVersion=41,version=3,refresh='10s',time={'from':'now-24h','to':'now'},timezone='browser',tags=['AERIS','EGN6216'],description='Read live service behavior by cohort. Demonstration requests are not independently inspected field outcomes. Panel tooltips define windows, units, support and actions.',templating={'list':[{'name':'cohort','label':'Record cohort','type':'custom','query':'test,genuine','current':{'text':'test','value':'test'},'options':[{'text':'test','value':'test','selected':True},{'text':'genuine','value':'genuine','selected':False}],'includeAll':False,'multi':False,'description':'test = controlled demonstrations; genuine = actual operator submissions. Neither is an inspected label by itself.'}]},panels=panels,links=links)
def link(title,url):return dict(title=title,url=url,type='link',targetBlank=False,includeVars=True,keepTime=False)
def main():
    health=panel(1,'Can AERIS serve a diagnosis? · health history','state-timeline',(0,0,24,5),[target('aeris_model_ready','Model ready'),target('aeris_app_up','UI assets'),target('up{job="aeris"}','Prometheus target UP')],'Green = available, red = unavailable, gaps = no observation. Scrape reachability is different from model readiness. Click the Targets link to inspect the actual scrape endpoint. UI assets are checked here; browser behavior is tested separately.',unit='none')
    health['fieldConfig']['defaults'].update(min=0,max=1,color={'mode':'thresholds'},noValue='Unknown',mappings=[{'type':'value','options':{'0':{'text':'DOWN','color':'red'},'1':{'text':'UP','color':'green'}}}],thresholds={'mode':'absolute','steps':[{'color':'red','value':None},{'color':'green','value':1}]})
    health['fieldConfig']['defaults']['color']={'mode':'fixed','fixedColor':'green'}
    health['options']=dict(showValue='auto',mergeValues=True,rowHeight=.75,alignValue='left',legend={'showLegend':False},tooltip={'mode':'single'})
    rate=lambda n:f'sum(rate(aeris_{n}{SEL}[$__rate_interval])) * 60'
    outcomes=trend(panel(2,'What is happening? · request outcomes / minute','timeseries',(0,5,12,8),[target(rate('review_total'),'Needs review'),target(f'clamp_min(({rate("requests_total")}) - ({rate("review_total")}) - ({rate("blocked_total")}) - ({rate("errors_total")}),0)','Research estimate'),target(rate('blocked_total'),'Rejected input'),target(rate('errors_total'),'Service error')],'Actual request rates for the selected cohort over time, smoothed by the Grafana rate interval. A research estimate is not equipment clearance. Idle time is zero traffic, not a failure.','reqpm'),True)
    latency=trend(panel(3,'How quickly does analysis return? · p50 / p95','timeseries',(12,5,12,8),[target(f'histogram_quantile({q}, sum by(le)(rate(aeris_inference_seconds_bucket{SEL}[$__rate_interval])))',name) for q,name in [(.5,'p50'),(.95,'p95')]],'Validation and model inference elapsed at ledger handoff; excludes HTTP/browser and final DB write. Quantiles are bucket estimates. No requests = gaps, not zero latency. The legend Last value is the last observed request interval, not current idle latency. Investigate sustained p95 above the provisional 5-second budget.','s'))
    eligible=f'(sum(increase(aeris_requests_total{SEL}[$__range])) - sum(increase(aeris_blocked_total{SEL}[$__range])) - sum(increase(aeris_errors_total{SEL}[$__range])))'
    review_expr=f'(sum(increase(aeris_review_total{SEL}[$__range])) / {eligible}) and ({eligible} >= 20)'
    workload=gauge(panel(4,'How much needs review? · selected period','gauge',(0,13,7,7),[target(review_expr,'Review required',True)],'Needs-review / eligible predictions in the selected period; at least 20 eligible requests. Scale 0–100%. Orange at 80% matches the workload alert threshold (alert itself uses 5 minutes for 1 minute). High workload calls for context/coverage investigation, never weaker review gates.','percentunit'),threshold=.8,no='Need 20+ requests')
    shift=gauge(panel(5,'Are sensors outside source range? · latest 100','gauge',(7,13,7,7),[target(f'aeris_source_shift_fraction{SEL} and on(cohort) (aeris_shift_support{SEL} >= 20)','Range exceedance',True)],'Fraction of temperature cells beyond 3 source-training standard deviations, averaged over the latest up to 100 valid requests in this cohort; minimum 20. Independent of the selected time range. Orange above 20% matches the shift alert. This is an unlabeled signal, not model accuracy or proof of bad data.','percentunit'),threshold=.2,no='Need 20+ requests')
    mix=bars(panel(6,'Which settings were analyzed? · selected period','barchart',(14,13,10,7),[target(f'sum by(setting)(increase(aeris_setting_requests_total{SEL}[$__range]))','Requests by setting',True,True)],'Estimated request counts in the selected period, from actual persisted inference activity. This is NOT training-set coverage or dataset quality. Controlled tests concentrated on CoolingSeason. Neutral bars compare traffic; no red/green severity meaning. For dataset support use the Data & model evidence link.'),'setting')
    alerts=panel(7,'What needs attention? · active alerts (empty = none)','table',(0,20,24,5),[target('ALERTS{alertname=~"Aeris.*",alertstate=~"pending|firing"}','Alerts',True,True)],'Current pending/firing AERIS alerts across cohorts. Empty table means none. Open Prometheus alerts for the rule and response instructions; owner identifies the responsible project role.')
    alerts['transformations']=[{'id':'organize','options':{'excludeByName':{'Time':True,'Value':True,'__name__':True,'job':True,'instance':True},'renameByName':{'alertname':'Alert','alertstate':'State','severity':'Severity','owner':'Owner','cohort':'Cohort'}}}];alerts['options']={'showHeader':True,'cellHeight':'sm'}
    links=[link('AERIS workspace','http://127.0.0.1:8510/'),link('Targets · UP / DOWN','http://127.0.0.1:9091/targets'),link('Prometheus alerts','http://127.0.0.1:9091/alerts'),link('Feedback evidence','/d/aeris-feedback'),link('Data & model evidence','http://127.0.0.1:8510/?view=experiments'),link('Metric definitions','http://127.0.0.1:8510/?view=monitoring')]
    primary=dashboard('aeris-operations','AERIS · Operator overview',[health,outcomes,latency,workload,shift,mix,alerts],links)
    support_parts=[]
    for metric,name in [('eligible_predictions','1 Analyzed'),('predictions_with_feedback','2 Reviewed'),('satisfaction_responses','3 Rated'),('verified_labels','4 Inspection records')]:support_parts.append(f'label_replace(aeris_{metric}{SEL},"stage","{name}","","")')
    support=bars(panel(21,'What review evidence exists? · all persisted records','barchart',(0,0,14,8),[target('sum by(stage)('+' or '.join(support_parts)+')','Support',True,True)],'Counts of available evidence in the selected cohort. Categories overlap and are not mutually exclusive. Test reviews and recorded inspection claims do not establish independent case quality. No timeframe filter is applied to these all-time counts.'),'stage')
    coverage=gauge(panel(22,'Review coverage · all persisted predictions','gauge',(14,0,10,8),[target(f'(aeris_predictions_with_feedback{SEL} / aeris_eligible_predictions{SEL}) and (aeris_eligible_predictions{SEL} > 0)','Reviewed',True)],'Unique eligible predictions with a saved review / all eligible predictions. Scale 0–100%; neutral blue because no field coverage objective has been established. Duplicate saves do not increase coverage. This is participation, not diagnostic accuracy.','percentunit'),no='No predictions')
    agreement_parts=[f'label_replace(aeris_{n}{SEL},"response","{n}","","")' for n in ['agree','disagree','unsure']]
    agreement=bars(panel(23,'How did reviewers respond? · response counts','barchart',(0,8,14,8),[target('sum by(response)('+' or '.join(agreement_parts)+')','Responses',True,True)],'Actual agree/disagree/unsure review counts. Unsure is explicit. These are subjective responses, not independently verified labels or accuracy. Zero bars mean no responses of that kind. Counts are all-time for the selected cohort.'),'response')
    satisfaction=gauge(panel(24,'Satisfaction · mean on a 1–5 scale','gauge',(14,8,10,8),[target(f'(aeris_satisfaction_sum{SEL}/aeris_satisfaction_responses{SEL}) and (aeris_satisfaction_responses{SEL}>0)','Mean rating',True)],'Average of actual 1–5 ratings; support is the Rated bar. No ratings = no value. Neutral color avoids implying a quality guarantee from a tiny or demonstration-only sample.','none'),low=1,high=5,no='No ratings')
    secondary=dashboard('aeris-feedback','AERIS · Review evidence',[support,coverage,agreement,satisfaction],[link('Operator overview','/d/aeris-operations'),link('Submit a review','http://127.0.0.1:8510/'),link('Metric definitions','http://127.0.0.1:8510/?view=monitoring')]);secondary['timepicker']={'hidden':True}
    DEST.mkdir(parents=True,exist_ok=True)
    for name,obj in [('aeris.json',primary),('aeris-feedback.json',secondary)]: (DEST/name).write_text(json.dumps(obj,indent=2),encoding='utf-8')
    print('Provisioned 7 operator panels and 4 separate review-evidence panels.')
if __name__=='__main__':main()
